<?php
namespace App\Http\Controllers; use App\Models\{Achievement,Announcement,Extracurricular,GalleryAlbum,News,Program,SchoolProfile,Teacher};
class PublicContentController extends Controller { public function home(){return view('public.home',['school'=>SchoolProfile::first(),'programs'=>Program::where('is_active',true)->take(4)->get(),'achievements'=>Achievement::latest()->take(4)->get(),'news'=>News::where('status','published')->latest('published_at')->take(3)->get(),'albums'=>GalleryAlbum::latest()->take(3)->get()]);} public function profile($page='about'){return view('public.profile', ['school'=>SchoolProfile::first(),'page'=>$page]);} public function teachers(){return view('public.collection',['title'=>'Guru & Tenaga Kependidikan','items'=>Teacher::where('is_active',true)->orderBy('sort_order')->paginate(12),'type'=>'teacher']);} public function programs(){return view('public.collection',['title'=>'Program Unggulan','items'=>Program::where('is_active',true)->paginate(12),'type'=>'program']);} public function achievements(){return view('public.collection',['title'=>'Prestasi','items'=>Achievement::latest()->paginate(12),'type'=>'achievement']);} public function extracurriculars(){return view('public.collection',['title'=>'Ekstrakurikuler','items'=>Extracurricular::where('is_active',true)->paginate(12),'type'=>'extracurricular']);} public function news(){return view('public.collection',['title'=>'Berita','items'=>News::where('status','published')->latest('published_at')->paginate(10),'type'=>'news']);} public function newsDetail($slug){return view('public.news-detail',['item'=>News::where('slug',$slug)->where('status','published')->firstOrFail()]);} public function announcements(){return view('public.collection',['title'=>'Pengumuman','items'=>Announcement::where('status','published')->latest('published_at')->paginate(10),'type'=>'announcement']);} public function gallery(){return view('public.collection',['title'=>'Galeri','items'=>GalleryAlbum::latest()->paginate(12),'type'=>'album']);} public function album($slug){return view('public.album',['album'=>GalleryAlbum::where('slug',$slug)->with('images')->firstOrFail()]);} }
